// Declaração de função (function declaration)
function somar(a, b) {
  return a + b;
}

// Declaração de variável cujo valor é uma expressão de função
const multiplicar = function (a, b) {
  return a * b;
};

// Expressão (arrow function) atribuída a uma constante
const dividir = (a, b) => a / b;

// Expressão condicional (ternário) usada dentro de uma declaração
const resultado = somar(2, 3) > 4 ? "maior" : "menor ou igual";

console.log(resultado); // "maior"

// ASI funciona bem na maioria dos casos
const a = 1
const b = 2
console.log(a + b) // 3, sem erro

// Armadilha clássica do ASI com "return"
function criarUtilizador() {
  return
  {
    nome: "Rita"
  };
}
console.log(criarUtilizador()); // undefined, não o objeto esperado

// Forma correta
function criarUtilizadorCorreto() {
  return {
    nome: "Rita"
  };
}
console.log(criarUtilizadorCorreto()); // { nome: "Rita" }

// Isto é um comentário de linha: explica a variável seguinte
const IVA = 0.23; // taxa de IVA em Portugal

/*
  Isto é um comentário de bloco.
  Pode ocupar várias linhas
  e é útil para explicações mais longas.
*/
function calcularTotalComIva(preco) {
  return preco * (1 + IVA);
}

/**
 * Calcula o preço final com IVA incluído.
 * @param {number} preco - Preço sem IVA.
 * @returns {number} Preço com IVA incluído.
 */
function calcularTotal(preco) {
  return calcularTotalComIva(preco);
}

