"use strict";

// 1. Declarações que definem o vocabulário do programa
const TAXA_DESCONTO = 0.1;

function calcularPrecoFinal(preco, temDesconto) {
  // Expressão ternária dentro de uma declaração de retorno
  return temDesconto ? preco * (1 - TAXA_DESCONTO) : preco;
}

// 2. Lógica principal, executada de cima para baixo
const precoOriginal = 50;
const precoComDesconto = calcularPrecoFinal(precoOriginal, true);

console.log(`Preço original: ${precoOriginal} EUR`);
console.log(`Preço final: ${precoComDesconto} EUR`);

