exercises.solution_code:
"use strict";

const IVA = 0.23;
const produtos = [
  { nome: "Cadeira", preco: 80 },
  { nome: "Mesa", preco: 150 }
];

function calcularPrecoComIva(preco) {
  const precoFinal = preco * (1 + IVA);
  return precoFinal;
}

const produtosComPrecoFinal = produtos.map((produto) => ({
  nome: produto.nome,
  precoFinal: calcularPrecoComIva(produto.preco)
}));

produtosComPrecoFinal.forEach((produto) => {
  console.log(`${produto.nome}: ${produto.precoFinal} EUR`);
});

console.table(produtosComPrecoFinal);
